 * Ищет активного пользователя по логину.
 *
 * @param login Логин пользователя (регистр не учитывается)
 * @return Опциональный объект с пользователем, если найден активный пользователь, иначе пустой Optional
 */
public Optional<User> findActive(String login) {
    // Получаем поток из коллекции всех пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Оставляем только тех пользователей, которые не заблокированы и срок действия их аккаунта еще не истек
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Возвращаем первого найденного пользователя, соответствующего условиям фильтрации
        .findFirst();
}
