/// <summary>
/// Выполняет асинхронное действие с повторными попытками при возникновении сетевых ошибок.
/// Использует экспоненциальную задержку между попытками для снижения нагрузки на сервер.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая Task&lt;int&gt;, которую нужно выполнить.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (int), если оно завершилось успешно.</returns>
/// <exception cref="InvalidOperationException">Бросается, если все попытки исчерпаны и ошибка не была перехвачена (теоретически недостижимое состояние).</exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл повторяется от 0 до attempts-1 раз (всего 'attempts' попыток)
    for (var i = 0; i < attempts; i++)
    {
        try 
        {
            // Пытаемся выполнить переданное асинхронное действие
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только сетевые ошибки (HttpRequestException)
            // Условие 'when (i < attempts - 1)' гарантирует, что мы не делаем задержку после последней неудачной попытки

            // Вычисляем экспоненциальную задержку: 200мс * 2^i
            // Например:
            //   i=0 -> 200 * 1 = 200 мс
            //   i=1 -> 200 * 2 = 400 мс
            //   i=2 -> 200 * 4 = 800 мс
