// Функция worker представляет собой функцию-работник (goroutine), которая обрабатывает задачи.
// Она читает задачи из канала jobs, выполняет их и отправляет результаты в канал results.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что счетчик WaitGroup будет уменьшен
    // после завершения работы этого воркера, независимо от того, как именно он завершится.
    defer wg.Done()

    // Цикл for range jobs непрерывно читает задачи из входного канала jobs.
    // Цикл автоматически завершится, когда канал jobs будет закрыт.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Возвращаются результат r и возможная ошибка err.
        r, err := process(j)

        // Если при обработке возникла ошибка:
        if err != nil {
            // Логируем ошибку с идентификатором задачи (j.ID) и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем эту задачу и переходим к следующей (не отправляем результат).
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в выходной канал results.
        // Это блокирующая операция: если буфер канала results заполнен,
        // воркер будет ждать, пока кто-то не заберет результат.
        results <- r
    }
}
