/**
 * Создаёт функцию-обёртку, которая откладывает вызов исходной функции `fn`
 * на указанное количество миллисекунд `ms`.
 * Если функция вызывается повторно до истечения таймера, предыдущий таймер
 * сбрасывается и устанавливается новый. Это позволяет "гасить" частые вызовы
 * (например, при вводе текста или скролле) и выполнять логику только после
 * паузы.
 *
 * @param fn - Исходная функция, которую нужно обернуть.
 * @param ms - Задержка в миллисекундах перед выполнением функции.
 * @returns Обёрнутая функция с теми же параметрами, что и у `fn`.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора текущего таймера.
  // Изначально она не определена, так как таймер ещё не создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и `fn`.
  return (...args: Parameters<T>) => {
    // Если существует активный таймер (t !== undefined),
    // очищаем его, чтобы отменить предыдущий запланированный вызов.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который вызовет `fn` через `ms` миллисекунд.
    // Сохраняем идентификатор таймера в переменную `t`, чтобы иметь возможность
    // отменить его при следующем вызове этой обёртки.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

