/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в HashMap.
/// Ключи приводятся к нижнему регистру и очищаются от пробелов по краям,
/// значения также очищаются от пробелов по краям.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    // Разбиваем исходную строку на части по разделителю ';'
    s.split(';')
        // Для каждой части пытаемся разделить её на ключ и значение по первому вхождению '='.
        // Если '=' не найдено (например, пустая часть или некорректный формат),
        // split_once вернёт None, и filter_map отфильтрует такой элемент.
        .filter_map(|p| p.split_once('='))
        // Преобразуем найденные пары (ключ, значение):
        // - ключ: убираем пробелы по краям (trim) и приводим к нижнему регистру (to_lowercase)
        // - значение: убираем пробелы по краям (trim) и оставляем как есть (to_string)
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string()))
        // Собираем все обработанные пары в HashMap<String, String>
        .collect()
}
